# --- models.py ---

import re
from typing import List


_MODEL_ID_PATTERN = re.compile(r"[A-Za-z0-9._-]+")


def parse_models(value: str) -> List[str]:
    models = []
    for item in value.split(","):
        model = item.strip()
        if not model or model in models:
            continue
        if not _MODEL_ID_PATTERN.fullmatch(model):
            raise ValueError(f"Invalid Agent Platform model ID: {model!r}")
        models.append(model)
    if not models:
        raise ValueError("At least one Agent Platform model must be configured.")
    return models


def select_model(requested: str, configured: List[str]) -> str:
    if not requested:
        return configured[0]
    if requested in configured:
        return requested
    for model in configured:
        if requested.endswith(f".{model}"):
            return model
    raise ValueError(f"Unsupported Agent Platform model: {requested!r}")

# --- messages.py ---

import base64
import binascii
import re
from typing import Any, Dict


_DATA_URL_PATTERN = re.compile(
    r"data:([^;,]+);base64,(.*)", flags=re.IGNORECASE | re.DOTALL
)
_THINKING_LEVELS = {"MINIMAL", "LOW", "MEDIUM", "HIGH"}


def _decode_data_url(value: str):
    match = _DATA_URL_PATTERN.fullmatch(value)
    if not match:
        return None, 0
    try:
        decoded = base64.b64decode(match.group(2), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64 media in a chat message.") from exc
    return {
        "inlineData": {
            "mimeType": match.group(1).lower(),
            "data": match.group(2),
        }
    }, len(decoded)


def message_parts(content: Any):
    if isinstance(content, str):
        return ([{"text": content}] if content else []), 0
    if not isinstance(content, list):
        return ([{"text": str(content)}] if content is not None else []), 0

    parts = []
    used_bytes = 0
    for item in content:
        if isinstance(item, str):
            parts.append({"text": item})
            continue
        if not isinstance(item, dict):
            continue

        item_type = item.get("type")
        if item_type in ("text", "input_text"):
            parts.append({"text": str(item.get("text", ""))})
            continue
        if item_type not in ("image_url", "input_image", "file"):
            continue

        source = item.get("image_url") or item.get("file") or item.get("url")
        if isinstance(source, dict):
            source = source.get("url") or source.get("data")
        if not isinstance(source, str):
            continue

        inline, size = _decode_data_url(source)
        if inline:
            parts.append(inline)
            used_bytes += size
        elif source.startswith("gs://"):
            mime_type = item.get("mime_type") or item.get("media_type")
            if mime_type:
                parts.append({"fileData": {"mimeType": mime_type, "fileUri": source}})
        else:
            # Agent Platform cannot consume arbitrary HTTP URLs as fileData.
            parts.append({"text": f"[Media URL: {source}]"})
    return parts, used_bytes


def generation_config(body: dict, thinking_level: str) -> Dict[str, Any]:
    config = {}
    mappings = {
        "temperature": "temperature",
        "top_p": "topP",
        "top_k": "topK",
        "max_tokens": "maxOutputTokens",
        "max_completion_tokens": "maxOutputTokens",
        "frequency_penalty": "frequencyPenalty",
        "presence_penalty": "presencePenalty",
        "seed": "seed",
    }
    for source, target in mappings.items():
        if body.get(source) is not None:
            config[target] = body[source]

    stop = body.get("stop")
    if stop:
        config["stopSequences"] = [stop] if isinstance(stop, str) else stop

    thinking_level = thinking_level.strip().upper()
    if thinking_level:
        if thinking_level not in _THINKING_LEVELS:
            raise ValueError(
                "THINKING_LEVEL must be MINIMAL, LOW, MEDIUM, HIGH, or empty."
            )
        config["thinkingConfig"] = {"thinkingLevel": thinking_level}
    return config

# --- files.py ---

import asyncio
import base64
import mimetypes
from pathlib import Path


async def uploaded_file_parts(files: list, initial_bytes: int, max_bytes: int):
    parts = []
    used_bytes = 0
    for wrapper in files:
        file_info = wrapper.get("file", wrapper) if isinstance(wrapper, dict) else {}
        if not isinstance(file_info, dict):
            continue

        path_value = file_info.get("path")
        meta = file_info.get("meta") or {}
        mime_type = (
            meta.get("content_type")
            or file_info.get("content_type")
            or mimetypes.guess_type(file_info.get("filename", ""))[0]
        )
        if not path_value or not mime_type:
            continue
        if str(path_value).startswith("gs://"):
            parts.append(
                {"fileData": {"mimeType": mime_type, "fileUri": path_value}}
            )
            continue

        path = Path(path_value)
        if not path.is_file():
            continue
        file_size = path.stat().st_size
        ensure_media_limit(initial_bytes + used_bytes + file_size, max_bytes)
        data = await asyncio.to_thread(path.read_bytes)
        used_bytes += len(data)
        parts.append(
            {
                "inlineData": {
                    "mimeType": mime_type,
                    "data": base64.b64encode(data).decode("ascii"),
                }
            }
        )
    return parts, used_bytes


def ensure_media_limit(size: int, max_bytes: int) -> None:
    if size > max_bytes:
        raise ValueError(
            f"Inline media exceeds the configured {max_bytes // (1024 * 1024)} MB limit."
        )

