import json
from typing import Any, Dict, List

from pydantic import BaseModel


_SCHEMA_FIELDS = {
    "type",
    "format",
    "description",
    "nullable",
    "enum",
    "items",
    "properties",
    "required",
    "minimum",
    "maximum",
    "minItems",
    "maxItems",
    "minLength",
    "maxLength",
    "pattern",
    "example",
    "anyOf",
    "propertyOrdering",
    "default",
}


def _clean_schema(value: Any) -> Any:
    if isinstance(value, list):
        return [_clean_schema(item) for item in value]
    if not isinstance(value, dict):
        return value

    cleaned = {}
    for key, item in value.items():
        if key not in _SCHEMA_FIELDS:
            continue
        if key == "properties" and isinstance(item, dict):
            cleaned[key] = {
                name: _clean_schema(schema) for name, schema in item.items()
            }
        else:
            cleaned[key] = _clean_schema(item)

    schema_type = cleaned.get("type")
    if isinstance(schema_type, list) and "null" in schema_type:
        non_null = [item for item in schema_type if item != "null"]
        cleaned["type"] = non_null[0] if len(non_null) == 1 else non_null
        cleaned["nullable"] = True
    return cleaned


def tool_declarations(tools: dict) -> List[Dict[str, Any]]:
    declarations = []
    for fallback_name, tool in tools.items():
        if not isinstance(tool, dict):
            continue
        spec = tool.get("spec") or {}
        if spec.get("type") == "function":
            spec = spec.get("function") or {}

        declaration = {"name": spec.get("name") or fallback_name}
        if spec.get("description"):
            declaration["description"] = spec["description"]
        if isinstance(spec.get("parameters"), dict):
            declaration["parameters"] = _clean_schema(spec["parameters"])
        declarations.append(declaration)
    return declarations


def _json_value(value: Any) -> Any:
    if isinstance(value, BaseModel):
        value = value.model_dump()
    return json.loads(json.dumps(value, default=str))


async def execute_tool(call: dict, tools: dict) -> Dict[str, Any]:
    name = call.get("name", "")
    tool = tools.get(name)
    response: Dict[str, Any]

    if not isinstance(tool, dict) or not callable(tool.get("callable")):
        response = {"error": f"Tool is unavailable: {name}"}
    else:
        arguments = call.get("args") or {}
        if not isinstance(arguments, dict):
            response = {"error": "Tool arguments must be an object."}
        else:
            try:
                result = await tool["callable"](**arguments)
                normalized = _json_value(result)
                response = (
                    normalized
                    if isinstance(normalized, dict)
                    else {"result": normalized}
                )
            except Exception as exc:
                response = {"error": str(exc)}

    function_response = {"name": name, "response": response}
    if call.get("id"):
        function_response["id"] = call["id"]
    return {"functionResponse": function_response}

# --- client.py ---

import json
from typing import Any, AsyncIterator, Dict, List
from urllib.parse import quote

import httpx


class AgentPlatformClient:
    async def stream_generate(
        self,
        model: str,
        payload: Dict[str, Any],
        *,
        api_key: str,
        base_url: str,
        timeout_seconds: float,
    ) -> AsyncIterator[Dict[str, Any]]:
        model_path = quote(model, safe="._-")
        url = (
            f"{base_url.rstrip('/')}/v1/publishers/google/models/"
            f"{model_path}:streamGenerateContent"
        )
        timeout = httpx.Timeout(timeout_seconds)

        async with httpx.AsyncClient(timeout=timeout) as client:
            async with client.stream(
                "POST",
                url,
                params={"alt": "sse", "key": api_key},
                headers={"Content-Type": "application/json"},
                json=payload,
            ) as response:
                if response.status_code >= 400:
                    raw_error = await response.aread()
                    raise RuntimeError(_upstream_error(response.status_code, raw_error))

                data_lines = []
                async for line in response.aiter_lines():
                    if not line:
                        if data_lines:
                            yield _decode_sse(data_lines)
                            data_lines = []
                        continue
                    if line.startswith("data:"):
                        data_lines.append(line[5:].lstrip())
                if data_lines:
                    yield _decode_sse(data_lines)


def _decode_sse(data_lines: List[str]) -> Dict[str, Any]:
    try:
        decoded = json.loads("\n".join(data_lines))
    except json.JSONDecodeError as exc:
        raise RuntimeError("Agent Platform returned malformed streaming data.") from exc
    if not isinstance(decoded, dict):
        raise RuntimeError("Agent Platform returned an unexpected streaming event.")
    return decoded


def _upstream_error(status_code: int, raw_error: bytes) -> str:
    message = raw_error.decode("utf-8", errors="replace")[:2000]
    try:
        error = json.loads(message).get("error", {})
        message = error.get("message") or message
    except (json.JSONDecodeError, AttributeError):
        pass
    return f"Agent Platform request failed ({status_code}): {message}"

# --- agent.py ---

import asyncio
from typing import AsyncIterator, Callable, Dict, Any



async def run_agent(
    model: str,
    payload: Dict[str, Any],
    tools: dict,
    max_tool_iterations: int,
    event_emitter,
    stream_generate: Callable,
) -> AsyncIterator[str]:
    for iteration in range(max_tool_iterations):
        model_parts = []
        function_calls = []
        prompt_feedback = None

        async for response in stream_generate(model, payload):
            if response.get("promptFeedback"):
                prompt_feedback = response["promptFeedback"]
            candidates = response.get("candidates") or []
            if not candidates:
                continue
            for part in (candidates[0].get("content") or {}).get("parts", []):
                model_parts.append(part)
                if "text" in part and not part.get("thought"):
                    yield part["text"]
                elif "inlineData" in part:
                    yield _render_inline_data(part["inlineData"])
                if "functionCall" in part:
                    function_calls.append(part["functionCall"])

        if not function_calls:
            if not model_parts and prompt_feedback:
                reason = prompt_feedback.get("blockReason", "unknown reason")
                raise RuntimeError(f"Agent Platform blocked the prompt: {reason}")
            return

        if iteration + 1 >= max_tool_iterations:
            raise RuntimeError("Maximum tool-call iterations reached.")

        await _emit_status(
            event_emitter,
            "Running "
            + ", ".join(call.get("name", "unknown tool") for call in function_calls),
            False,
        )
        responses = await asyncio.gather(
            *(execute_tool(call, tools) for call in function_calls)
        )
        await _emit_status(event_emitter, "Tool execution complete", True)

        payload["contents"].append({"role": "model", "parts": model_parts})
        payload["contents"].append({"role": "user", "parts": responses})

    raise RuntimeError("Maximum tool-call iterations reached.")


def _render_inline_data(inline_data: dict) -> str:
    mime_type = inline_data.get("mimeType", "application/octet-stream")
    data = inline_data.get("data", "")
    if mime_type.startswith("image/"):
        return f"\n![Generated image](data:{mime_type};base64,{data})\n"
    return f"\n[Generated {mime_type}](data:{mime_type};base64,{data})\n"


async def _emit_status(emitter, description: str, done: bool) -> None:
    if not emitter:
        return
    try:
        await emitter(
            {
                "type": "status",
                "data": {"description": description, "done": done},
            }
        )
    except Exception:
        # UI status delivery must not fail the model request.
        pass

# --- pipe.py ---

from typing import Any, Dict, List, Optional



class Pipe:
    """Open WebUI manifold pipe for the Google Agent Platform Model API."""

    name = "Google/"
    Valves = Valves

    def __init__(self, client=None):
        self.valves = self.Valves()
        self.client = client or AgentPlatformClient()

    def pipes(self) -> List[Dict[str, str]]:
        return [
            {"id": model, "name": model}
            for model in parse_models(self.valves.MODELS)
        ]

    async def pipe(
        self,
        body: dict,
        __tools__: Optional[dict] = None,
        __files__: Optional[list] = None,
        __event_emitter__=None,
    ):
        if not self.valves.GOOGLE_API_KEY.strip():
            raise ValueError("Google Agent Platform API key is not configured.")

        tools = __tools__ or {}
        model = select_model(body.get("model", ""), parse_models(self.valves.MODELS))
        payload = await self._build_request(body, tools, __files__ or [])

        async def stream_generate(selected_model, request):
            async for response in self.client.stream_generate(
                selected_model,
                request,
                api_key=self.valves.GOOGLE_API_KEY,
                base_url=self.valves.API_BASE_URL,
                timeout_seconds=self.valves.REQUEST_TIMEOUT_SECONDS,
            ):
                yield response

        output = run_agent(
            model,
            payload,
            tools,
            self.valves.MAX_TOOL_ITERATIONS,
            __event_emitter__,
            stream_generate,
        )
        if body.get("stream", False):
            return output

        chunks = [chunk async for chunk in output]
        return "".join(chunks)

    async def _build_request(
        self, body: dict, tools: dict, files: list
    ) -> Dict[str, Any]:
        contents = []
        system_parts = []
        inline_bytes = 0
        max_inline_bytes = self.valves.MAX_INLINE_MEDIA_MB * 1024 * 1024

        for message in body.get("messages", []):
            role = message.get("role", "user")
            parts, used_bytes = message_parts(message.get("content", ""))
            inline_bytes += used_bytes
            ensure_media_limit(inline_bytes, max_inline_bytes)

            if role in ("system", "developer"):
                system_parts.extend(part for part in parts if "text" in part)
                continue

            gemini_role = "model" if role == "assistant" else "user"
            contents.append(
                {"role": gemini_role, "parts": parts or [{"text": ""}]}
            )

        file_parts, used_bytes = await uploaded_file_parts(
            files, inline_bytes, max_inline_bytes
        )
        inline_bytes += used_bytes
        ensure_media_limit(inline_bytes, max_inline_bytes)
        if file_parts:
            for content in reversed(contents):
                if content["role"] == "user":
                    content["parts"].extend(file_parts)
                    break
            else:
                contents.append({"role": "user", "parts": file_parts})

        if not contents:
            contents.append({"role": "user", "parts": [{"text": ""}]})

        payload: Dict[str, Any] = {"contents": contents}
        if system_parts:
            payload["systemInstruction"] = {"parts": system_parts}

        config = generation_config(body, self.valves.THINKING_LEVEL)
        if config:
            payload["generationConfig"] = config

        declarations = tool_declarations(tools)
        if declarations:
            payload["tools"] = [{"functionDeclarations": declarations}]
        return payload
